import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parent.parent))

from notifications.sms import delivery_status, queue_sms, sent_messages


def main() -> None:
    status = delivery_status()
    resent = []
    for msg in sent_messages():
        if status.get(msg.id) == "failed":
            new_msg = queue_sms(msg.household_id, msg.template_id, msg.params)
            resent.append(new_msg.id)
    print(f"Resent {len(resent)} failed SMS: {resent}")


if __name__ == "__main__":
    main()
